  var pageNum = Math.max(1, Math.floor(Number(pageIndex) || 0) + 1);
  var pageEl = sourcePager.querySelector('.pdfjs-page[data-page-num="' + pageNum + '"]');
  if (!pageEl) return;
  var top = pageEl.offsetTop || 0;
