  function stripNativeTitleTooltips(root) {
    root = root || document;
    if (!root || !root.querySelectorAll) return;
    try {
      Array.from(root.querySelectorAll('[title]')).forEach(function(el) {
        if (el.hasAttribute && el.hasAttribute('data-native-tooltip')) return;
        el.removeAttribute('title');
      });
    } catch (_titleErr) {}
  }

  stripNativeTitleTooltips(document);
  if (typeof MutationObserver === 'function') {
    try {
      var nativeTitleObserver = new MutationObserver(function(records) {
        records.forEach(function(record) {
          if (record.type === 'attributes' && record.attributeName === 'title' && record.target) {
            try {
              if (!(record.target.hasAttribute && record.target.hasAttribute('data-native-tooltip'))) {
                record.target.removeAttribute('title');
              }
            } catch (_attrErr) {}
            return;
          }
          Array.from(record.addedNodes || []).forEach(function(node) {
            if (!node || node.nodeType !== 1) return;
            if (node.hasAttribute && node.hasAttribute('title') && !(node.hasAttribute && node.hasAttribute('data-native-tooltip'))) {
              node.removeAttribute('title');
            }
            stripNativeTitleTooltips(node);
          });
        });
      });
      nativeTitleObserver.observe(document.documentElement || document.body, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ['title']
      });
    } catch (_observerErr) {}
  }

