    var entryRowId = parseInt(opts.entry_row_id || (editContext && editContext.snapshot ? editContext.snapshot.entry_row_id : 0) || 0, 10) || 0;
    var storageKind = String(opts.storage_kind || (editContext && editContext.snapshot ? editContext.snapshot.storage_kind : '') || '');
