      + '    <label>Part of speech' + (editMode ? '' : ' *') + '</label>'
      + '    <input type="text" id="ef-pos" class="userdict-input" value="' + escapeHtml(pos) + '"' + (editMode ? '' : ' required') + '>'
      + '  </div>'
      + '  <div class="userdict-field-full">'
      + '    <label>Glosses' + (editMode ? '' : ' *') + '</label>'
      + '    <div id="ef-glosses-list" class="ef-dynamic-list"></div>'
      + '    <button type="button" id="ef-add-gloss" class="ef-add-btn">+ Add gloss</button>'
      + '  </div>'
      + '  <div class="userdict-field-full">'
